/** macOS libm results (libsystem_m) for arguments where V8's Math.* differs in the last bit. */
const LIBM: Record<string, [number, number][]> = {exp:[[2.1928303241729736,8.96053848696838],[2.1741538047790527,8.794739905700885],[2.168660879135132,8.746563489210471],[2.158773422241211,8.660508354035029],[2.126913547515869,8.388934764467857],[2.043419122695923,7.716949339762553],[2.00716495513916,7.4421884726345615],[2.006066083908081,7.434014957468523],[2.004967451095581,7.4258521894710485],[1.9983758926391602,7.377065218405101],[1.9950801134109497,7.352792061547787],[1.9928828477859497,7.336653760862791]],log:[[1.1033062897692765,0.09831138963733459],[1.116629123942101,0.11031443625333133],[1.1186677651188148,0.11213848186617859],[1.1339716828170368,0.12572623393296406],[1.1486508893753402,0.13858811403454016],[1.1593200784149078,0.14783369397398793],[1.2253126156527077,0.20319600789080472],[1.2726269331663145,0.24108321548252454],[1.359733395002705,0.30728864744471746],[1.3855527063519852,0.3260991259917723],[1.4665164957684038,0.3828898577651532],[1.4746710604752598,0.388434955074108]],sin:[[0.30716198802658917,0.3023546774796483],[0.5852282913327567,0.552389697182328],[0.7939232616261228,0.71310916778611],[0.8050059851971988,0.7208347913936098],[0.8276377624988681,0.7363350968747623],[0.8450283109435291,0.7479899027341014],[0.9247092172418624,0.7984457263150305],[0.9311409110640692,0.8023014944151848],[1.1150215849529022,0.8979202887908216],[1.1384503611476773,0.9079852847198359],[2.095176154277694,0.8656346137259542],[2.124423607222317,0.8506229846658299]],cos:[[0.13351768918196757,0.9910997471790189],[1.3854423122961992,0.18429449567812534],[1.303760925024272,0.2638730752517202],[0.2921681237122308,0.957621643962047],[0.3157300695504218,0.9505699379743241],[0.3188716685706311,0.9495897490932582],[1.2346459338331823,0.3298553950602534],[1.2315042879995945,0.33281957489445263],[0.38170353194137024,0.9280314135129298],[0.42882740021106297,0.9094539472683497],[1.0634290915187374,0.48587782669755164],[1.0477211432310696,0.49954648748049363]]};

function decode(b64: string): Float32Array {
  const bin = atob(b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new Float32Array(u8.buffer);
}

function baseState(): Record<string, unknown> {
  const s: Record<string, unknown> = {};
  HARMOR_KEYS.forEach((k, i) => { s[k] = BASE.params[i]; });
  s.hA = BASE.A;
  s.hB = BASE.B;
  s.hG = { ...BASE.G };
  return s;
}

function fnv(x: Float32Array): number {
  const u = new Uint32Array(1);
  const f = new Float32Array(u.buffer);
  let h = 0x811c9dc5;
  for (let i = 0; i < x.length; i++) {
    f[0] = x[i] + 0;
    const w = u[0];
    for (let k = 0; k < 4; k++) {
      h ^= (w >>> (8 * k)) & 0xff;
      h = Math.imul(h, 0x01000193) >>> 0;
    }
  }
  return h >>> 0;
}

/** Run a case the way FL's render calls went: returns the interleaved output (N frames). */
function run(c: Case, block = 0): Float32Array {
  const inp = INPUTS[String(c.prec)];
  const x = decode(inp.b64);
  const blocks = c.blocks ?? inp.blocks;
  const state = baseState();
  state.hG = { ...(state.hG as object), ...c.G };
  for (const [k, v] of Object.entries(c.p)) state[HARMOR_KEYS[+k]] = v;
  const fx = new HarmorFx(44100, 512);
  fx.setParams(state);
  const out = new Float32Array(2 * N);
  const L = new Float32Array(512), R = new Float32Array(512);
  let pos = 0, prev = 0;
  for (const [len0, nv] of blocks) {
    const len = Math.min(len0, N - pos);
    let changed = false;
    for (const a of c.at ?? []) if (a[0] === pos) { state[HARMOR_KEYS[a[1]]] = a[2]; changed = true; }
    if (changed) fx.setParams({ ...state });
    const voices = prev + (pos === 0 ? 1 : 0);
    // optionally split FL's calls into smaller ones (must not matter for these settings)
    const step = block > 0 ? block : len;
    for (let o = 0; o < len; o += step) {
      const m = Math.min(step, len - o);
      for (let i = 0; i < m; i++) { L[i] = x[2 * (pos + o + i)]; R[i] = x[2 * (pos + o + i) + 1]; }
      fx.process(L, R, m, 140, null, null, voices);
      for (let i = 0; i < m; i++) { out[2 * (pos + o + i)] = L[i]; out[2 * (pos + o + i) + 1] = R[i]; }
    }
    pos += len;
    prev = nv;
    if (pos >= N) break;
  }
  return out;
}

describe('Harmor global FX: FL bit-exact vectors', () => {
  for (const c of CASES) {
    it(c.name, () => {
      const y = run(c);
      const idx = [1, 701, 2001, 3001, 4095];
      expect(idx.map((i) => y[i])).toEqual(c.s.map((v) => Math.fround(v)));
      let peak = 0;
      for (let i = 0; i < y.length; i++) peak = Math.max(peak, Math.abs(y[i]));
      expect(peak).toBe(Math.fround(c.peak));
      expect(fnv(y)).toBe(c.hash);
    });
  }
});

describe('fx-libm: macOS libm exp / log / sin / cos bit for bit', () => {
  const F: Record<string, (x: number) => number> = { exp: libmExp, log: libmLog, sin: libmSin, cos: libmCos };
  for (const [fn, rows] of Object.entries(LIBM)) {
    it(fn, () => {
      for (const [x, y] of rows) expect(F[fn](x)).toBe(y);
    });
  }
  it('special values', () => {
    expect(libmExp(0)).toBe(1);
    expect(libmExp(-Infinity)).toBe(0);
    expect(libmExp(Infinity)).toBe(Infinity);
    expect(libmExp(710)).toBe(Infinity);
    expect(libmExp(-800)).toBe(0);
    expect(libmLog(1)).toBe(0);
    expect(libmLog(0)).toBe(-Infinity);
    expect(Number.isNaN(libmLog(-1))).toBe(true);
    expect(libmSin(0)).toBe(0);
    expect(libmCos(0)).toBe(1);
    expect(libmCos(Math.PI / 2)).toBe(6.123233995736766e-17);
  });
});

describe('harmorPartGain (FL part+0x14, 0xcac00 / 0xd25dc)', () => {
  it('one part enabled: mix 0.5', () => {
    const s = baseState();
    expect(harmorPartGain(s, 0)).toBe(0.5);
    expect(harmorPartGain(s, 1)).toBe(0.5);
  });
  // [partMix, preVol, A vol, B vol, FL gain A, FL gain B] with both parts enabled (FL host, preset Arp/Cubist)
  const FL: number[][] = [
    [500, 1000, 1000, 1000, 0.39774754643440247, 0.39774754643440247],
    [0, 1500, -700, 2000, -0.6831222176551819, 2.890578283052921e-16],
    [1000, 300, 1, -1, 3.695083650933998e-21, -6.034529360476881e-05],
    [333, 999, 0, -2000, 0.0, -1.1221286058425903],
    [871, 0, 1500, -1000, 0.0, -0.0],
    [500, 2000, -2000, 999, -6.3639607429504395, 1.5883700847625732],
    [1, 1001, 999, -999, 0.562498927116394, -0.0008835605694912374],
    [999, 1999, 1999, 3, 0.014101235195994377, 0.003709341399371624],
  ];
  for (const [pm, pv, va, vb, ga, gb] of FL) {
    it(`mix ${pm} pre ${pv} vols ${va} / ${vb}`, () => {
      const s = baseState();
      s.hA = { ...BASE.A, on: 1 };
      s.hB = { ...BASE.B, on: 1 };
      s.partMix = pm;
      s.preVol = pv;
      s.a_vol = va;
      s.b_vol = vb;
      expect(harmorPartGain(s, 0)).toBe(ga);
      expect(harmorPartGain(s, 1)).toBe(gb);
    });
  }
});

describe('Harmor global FX: behaviour', () => {
  const blocks = (fx: HarmorFx, n: number, fill: (i: number) => number, voices = 1) => {
    const L = new Float32Array(256), R = new Float32Array(256);
    let peak = 0, finite = true;
    for (let b = 0; b < n; b++) {
      for (let i = 0; i < 256; i++) { L[i] = fill(b * 256 + i); R[i] = fill(b * 256 + i + 7); }
      fx.process(L, R, 256, 120, null, null, voices);
      for (let i = 0; i < 256; i++) {
        if (!Number.isFinite(L[i]) || !Number.isFinite(R[i])) finite = false;
        peak = Math.max(peak, Math.abs(L[i]), Math.abs(R[i]));
      }
    }
    return { peak, finite };
  };

  it('all FX off: output = input (dry unit only), tail 30 ms', () => {
    const fx = new HarmorFx(48000, 256);
    fx.setParams(baseState());
    const L = new Float32Array(256).map((_, i) => Math.sin(i * 0.1));
    const R = L.map((v) => -v);
    const L0 = L.slice(), R0 = R.slice();
    fx.process(L, R, 256, 120, null, null, 1);
    expect(L).toEqual(L0);
    expect(R).toEqual(R0);
    expect(fx.tail()).toBeCloseTo(1440 / 48000, 12);
  });

  it('dry bus is added at the dry unit', () => {
    const fx = new HarmorFx(44100, 64);
    fx.setParams(baseState());
    const L = new Float32Array(64).fill(0.25), R = new Float32Array(64).fill(-0.5);
    const dL = new Float32Array(64).fill(0.125), dR = new Float32Array(64).fill(0.5);
    fx.process(L, R, 64, 120, dL, dR, 1);
    expect(L[10]).toBe(0.375);
    expect(R[10]).toBe(0);
  });

  it('tail: 530 ms with distortion, Infinity with delay', () => {
    const s = baseState();
    s.hG = { ...(s.hG as object), distMode: 1 };
    const fx = new HarmorFx(44100, 64);
    fx.setParams(s);
    expect(fx.tail()).toBeCloseTo(23373 / 44100, 12);
    s.delOn = 1;
    fx.setParams({ ...s });
    const L = new Float32Array(64), R = new Float32Array(64);
    fx.process(L, R, 64, 120, null, null, 0);
    expect(fx.tail()).toBe(Infinity);
  });

  it('distortion stops after the FX tail once the voices end', () => {
    const s = baseState();
    s.hG = { ...(s.hG as object), distMode: 2 };
    s.distAsym = 400; // DC offset: audible while the unit runs
    const fx = new HarmorFx(44100, 256);
    fx.setParams(s);
    const r1 = blocks(fx, 4, () => 0, 0);
    expect(r1.peak).toBeGreaterThan(1e-3);
    blocks(fx, 100, () => 0, 0); // 25600 frames > 23373
    const r2 = blocks(fx, 2, () => 0.5, 0);
    expect(r2.peak).toBe(0.5); // the distortion no longer runs: bus 0 passes unchanged
  });

  it('extreme settings stay finite', () => {
    const s = baseState();
    s.hG = { ...(s.hG as object), distMode: 11, precision: 2, fxOrder: [2, 0, 4, 1, 3, 5] };
    Object.assign(s, { distAmt: 1000, distAsym: -500, distWet: 2000, distMix: -1000, distHC: 500,
      delOn: 1, delMode: 2, delFb: 1000, delTime: -384, delOfs: 512, delVol: 1000, delPan: -128, delLC: 1000, delHC: 400, delDamp: 1, postVol: 2000 });
    const fx = new HarmorFx(96000, 256);
    fx.setParams(s);
    const r = blocks(fx, 60, (i) => 4 * Math.sin(i * 0.37) * Math.sin(i * 0.0011), 1);
    expect(r.finite).toBe(true);
    for (let m = 1; m <= 11; m++) {
      const f2 = new HarmorFx(22050, 256);
      f2.setParams({ ...s, hG: { ...(s.hG as object), distMode: m, precision: m % 3 } });
      expect(blocks(f2, 8, (i) => 30 * Math.sin(i * 0.7), 1).finite).toBe(true);
    }
  });

  it('compression: silence gate passes silence through, every type stays finite', () => {
    for (let t = 1; t <= 4; t++) {
      const s = baseState();
      s.hG = { ...(s.hG as object), compType: t };
      Object.assign(s, { compAmt: 1000, compLow: 2000, compMid: 2000, compHigh: 2000 });
      const fx = new HarmorFx(48000, 256);
      fx.setParams(s);
      expect(blocks(fx, 4, () => 0, 0).peak).toBe(0);
      const r = blocks(fx, 40, (i) => 20 * Math.sin(i * 0.05) * Math.sin(i * 0.0007), 1);
      expect(r.finite).toBe(true);
      expect(r.peak).toBeGreaterThan(0.1);
      expect(fx.tail()).toBe(Infinity);
    }
  });

  it('reset clears the delay', () => {
    const s = baseState();
    Object.assign(s, { delOn: 1, delFb: 900, delTime: 10 });
    const fx = new HarmorFx(44100, 256);
    fx.setParams(s);
    blocks(fx, 20, (i) => (i < 300 ? Math.sin(i) : 0), 1);
    fx.reset();
    expect(blocks(fx, 20, () => 0, 1).peak).toBe(0);
  });
});

